diff --git a/packs/cloudflare-site/bump-version.mjs b/packs/cloudflare-site/bump-version.mjs
index 458edf3f..965ac071 100644
--- a/packs/cloudflare-site/bump-version.mjs
+++ b/packs/cloudflare-site/bump-version.mjs
@@ -2,13 +2,21 @@
 //
 // The version a release cuts, and the copy of it the pages carry.
 //
-// Scheme: `<major>.<mmdd>.<n>`
+// Scheme: `<major>.<ymmdd>.<build>`
 //   - major  is carried over from the version already recorded — a generation
 //            statement, raised by hand and never by a release
-//   - minor  is the release date as zero-padded UTC month+day
-//   - patch  is a monotonic counter: previous patch + 1, so it advances even when
+//   - minor  is the release date: years since EPOCH_YEAR, then zero-padded UTC
+//            month and day. 2026-09-17 is 10917; 2027-01-01 is 20101.
+//   - build  is a monotonic counter: previous build + 1, so it advances even when
 //            the day (and therefore the minor) rolls over
 //
+// THE YEAR OFFSET is what makes the minor mean "later". A bare MMDD runs backwards
+// every New Year — 1231 is followed by 0101 — so the one thing every reader of a
+// version assumes stopped being true once a year, and the ordering rested entirely
+// on the build counter. Counting years from a fixed epoch instead makes the minor
+// strictly increasing with no wrap to absorb: the offset simply grows, taking the
+// minor to six digits in 2035, which is still numerically above 2034's five.
+//
 // `package.json` is the single source of truth, and the release commits the bumped
 // files back to the default branch — so the number in the repo always names the
 // last release that actually went out.
@@ -26,18 +34,29 @@ import { join } from 'node:path';
 import { pathToFileURL } from 'node:url';
 import { parseWranglerConfig, publishedDir, WRANGLER_CONFIGS } from './lib.mjs';

-// The stamp as authored: `title="version 1.0913.7"`, anywhere on a page. Exported
+// The stamp as authored: `title="version 1.10913.7"`, anywhere on a page. Exported
 // so the generator and the drift check spell it one way.
 export const STAMP = /title="version [^"]*"/g;

-// The version that follows `current`, released at `now`. An unparseable patch
+// Year zero of the scheme: 2026 is the offset's 1, so the minor never carries a
+// leading zero and never repeats. Moving it would renumber every release ever cut,
+// so it is a constant rather than a setting.
+export const EPOCH_YEAR = 2025;
+
+// The date half of the version, for `now`: `<years since EPOCH_YEAR><MM><DD>`, all
+// read in UTC because a runner's local zone is not the repo's and a version must not
+// depend on which region the job landed in.
+export function releaseDate(now = new Date()) {
+  return `${now.getUTCFullYear() - EPOCH_YEAR}${now.toISOString().slice(5, 10).replace('-', '')}`;
+}
+
+// The version that follows `current`, released at `now`. An unparseable build
 // (the initial "1.0.0", a hand-typed string) counts as 0, so the first bump lands
 // on 1 rather than NaN.
 export function nextVersion(current, now = new Date()) {
-  const [major, , patch] = String(current ?? '').split('.');
-  const prevPatch = Number.parseInt(patch, 10);
-  const mmdd = now.toISOString().slice(5, 10).replace('-', '');
-  return `${/^\d+$/.test(major ?? '') ? major : '1'}.${mmdd}.${(Number.isFinite(prevPatch) ? prevPatch : 0) + 1}`;
+  const [major, , build] = String(current ?? '').split('.');
+  const prevBuild = Number.parseInt(build, 10);
+  return `${/^\d+$/.test(major ?? '') ? major : '1'}.${releaseDate(now)}.${(Number.isFinite(prevBuild) ? prevBuild : 0) + 1}`;
 }

 // One page's stamp. A page carrying no `title="version …"` is returned unchanged —
diff --git a/packs/cloudflare-site/test/bump-version.test.mjs b/packs/cloudflare-site/test/bump-version.test.mjs
index 72051959..5e0d94cf 100644
--- a/packs/cloudflare-site/test/bump-version.test.mjs
+++ b/packs/cloudflare-site/test/bump-version.test.mjs
@@ -14,20 +14,43 @@ const withTemp = (fn) => {
 // The patch is a monotonic counter rather than a per-day one, so two releases either
 // side of midnight cannot land on the same version.
 test('the version advances across a day rollover', () => {
-  const eve = nextVersion('1.0903.57', new Date('2026-09-03T20:00:00Z'));
-  assert.equal(eve, '1.0903.58');
-  assert.equal(nextVersion(eve, new Date('2026-09-04T20:00:00Z')), '1.0904.59');
+  const eve = nextVersion('1.10903.57', new Date('2026-09-03T20:00:00Z'));
+  assert.equal(eve, '1.10903.58');
+  assert.equal(nextVersion(eve, new Date('2026-09-04T20:00:00Z')), '1.10904.59');
+});
+
+// The whole point of the year offset. A bare MMDD goes BACKWARDS every New Year —
+// 1231 then 0101 — so the minor could not be read as "later means bigger" and the
+// ordering rested entirely on the patch counter. Counting years from the epoch makes
+// the minor strictly increasing forever, with no wrap to absorb.
+test('the minor keeps increasing across a year rollover', () => {
+  const eve = nextVersion('1.11230.4', new Date('2026-12-31T20:00:00Z'));
+  assert.equal(eve, '1.11231.5');
+  const day = nextVersion(eve, new Date('2027-01-01T20:00:00Z'));
+  assert.equal(day, '1.20101.6');
+  assert.ok(Number(day.split('.')[1]) > Number(eve.split('.')[1]),
+    'the new year must sort above the old one');
+});
+
+// A year is one step, whatever its digits do: 2035 takes the offset to two digits and
+// the minor to six, which is still numerically above 2034's five.
+test('the offset keeps ordering when it reaches two digits', () => {
+  const y2034 = nextVersion('1.91231.9', new Date('2034-12-31T20:00:00Z'));
+  assert.equal(y2034, '1.91231.10');
+  const y2035 = nextVersion(y2034, new Date('2035-01-01T20:00:00Z'));
+  assert.equal(y2035, '1.100101.11');
+  assert.ok(Number(y2035.split('.')[1]) > Number(y2034.split('.')[1]));
 });

 test('an unparseable recorded version still yields a first release', () => {
-  assert.equal(nextVersion('1.0.0', new Date('2026-09-04T20:00:00Z')), '1.0904.1');
-  assert.equal(nextVersion(undefined, new Date('2026-09-04T20:00:00Z')), '1.0904.1');
+  assert.equal(nextVersion('1.0.0', new Date('2026-09-04T20:00:00Z')), '1.10904.1');
+  assert.equal(nextVersion(undefined, new Date('2026-09-04T20:00:00Z')), '1.10904.1');
 });

 // The major is a generation statement a person raises by hand; a release carries it
 // over and never touches it.
 test('the release carries the recorded major over', () => {
-  assert.equal(nextVersion('3.0903.57', new Date('2026-09-04T20:00:00Z')), '3.0904.58');
+  assert.equal(nextVersion('3.10903.57', new Date('2026-09-04T20:00:00Z')), '3.10904.58');
 });

 test('the stamp rewrites every version title and leaves a page without one alone', () => {
@@ -56,16 +79,16 @@ test('stamping reaches pages nested under the published tree', () => {
 test('a stamp-only run repairs the pages and consumes no version', () => {
   withTemp((root) => {
     mkdirSync(join(root, 'site'));
-    writeFileSync(join(root, 'package.json'), JSON.stringify({ version: '1.0910.4' }, null, 2));
+    writeFileSync(join(root, 'package.json'), JSON.stringify({ version: '1.10910.4' }, null, 2));
     writeFileSync(join(root, 'wrangler.json'), JSON.stringify({ assets: { directory: './site' } }));
     writeFileSync(join(root, 'site', 'index.html'), '<b title="version 1.0801.1">x</b>');

-    assert.equal(bump(root, { stampOnly: true }), '1.0910.4');
-    assert.match(readFileSync(join(root, 'site', 'index.html'), 'utf8'), /version 1\.0910\.4/);
-    assert.equal(JSON.parse(readFileSync(join(root, 'package.json'), 'utf8')).version, '1.0910.4');
+    assert.equal(bump(root, { stampOnly: true }), '1.10910.4');
+    assert.match(readFileSync(join(root, 'site', 'index.html'), 'utf8'), /version 1\.10910\.4/);
+    assert.equal(JSON.parse(readFileSync(join(root, 'package.json'), 'utf8')).version, '1.10910.4');

-    assert.equal(bump(root, { now: new Date('2026-09-11T00:00:00Z') }), '1.0911.5');
-    assert.equal(JSON.parse(readFileSync(join(root, 'package.json'), 'utf8')).version, '1.0911.5');
-    assert.match(readFileSync(join(root, 'site', 'index.html'), 'utf8'), /version 1\.0911\.5/);
+    assert.equal(bump(root, { now: new Date('2026-09-11T00:00:00Z') }), '1.10911.5');
+    assert.equal(JSON.parse(readFileSync(join(root, 'package.json'), 'utf8')).version, '1.10911.5');
