#!/usr/bin/env python3
"""Condense a captured session JSONL into a readable timeline.

argv: <jsonl path> [text-cap] [result-cap]
"""
import json, sys

path = sys.argv[1]
TCAP = int(sys.argv[2]) if len(sys.argv) > 2 else 1200
RCAP = int(sys.argv[3]) if len(sys.argv) > 3 else 300


def clip(s, n):
    s = " ".join(str(s).split())
    return s if len(s) <= n else s[:n] + f" …[+{len(s)-n}]"


for line in open(path):
    line = line.strip()
    if not line:
        continue
    e = json.loads(line)
    ts = (e.get("timestamp") or "")[11:19]
    typ = e.get("type")
    if typ == "attachment":
        a = e.get("attachment", {})
        if a.get("type") == "hook_additional_context":
            print(f"{ts} HOOK  {clip(a.get('content'), 200)}")
        continue
    msg = e.get("message") or {}
    role = msg.get("role") or typ
    content = msg.get("content")
    if isinstance(content, str):
        print(f"{ts} {role.upper():9} {clip(content, TCAP)}")
        continue
    if not isinstance(content, list):
        continue
    for c in content:
        if not isinstance(c, dict):
            continue
        k = c.get("type")
        if k == "text":
            print(f"{ts} {role.upper():9} {clip(c.get('text'), TCAP)}")
        elif k == "thinking":
            print(f"{ts} THINK     {clip(c.get('thinking'), 400)}")
        elif k == "tool_use":
            print(f"{ts} TOOL      {c.get('name')} {clip(json.dumps(c.get('input')), 400)}")
        elif k == "tool_result":
            body = c.get("content")
            if isinstance(body, list):
                body = " ".join(x.get("text", "") for x in body if isinstance(x, dict))
            err = " ERR" if c.get("is_error") else ""
            print(f"{ts}   result{err} {clip(body, RCAP)}")

