1	// The rule index a pack README carries: one row per rule in the pack's
2	// RULES.md, each row stating that rule's length, the severity of ignoring
3	// it and the reason it exists (packs/README.md#the-rule-index-a-pack-readme-carries).
4	//
5	// A rule's length is derived data, so it is computed here and compared against
6	// the README by rule-index.test.mjs rather than hand-maintained in the two dozen
7	// pack READMEs whose prose is appended to several times a week. The row states
8	// the size BAND rather than the count, because nothing reads the digit: the
9	// session-start summary counts the prose itself and no other reader opens this
10	// index, so an exact figure only bought a red build every time a rule moved by
11	// one word (#2006).
12	
13	// The two closed vocabularies a row's Severity and Reason cells are drawn from,
14	// spelled once here and described in packs/README.md.
15	export const SEVERITIES = ['critical', 'high', 'medium', 'low'];
16	export const REASONS = ['correctness', 'performance', 'complexity', 'legal'];
17	
18	// The ladder a rule's length is reported on: an upper bound per rung, and an
19	// open top so no length is unclassifiable. The corpus reaches ~200 words today,
20	// so the last two rungs stand empty — kept because a rule that grows past 200
21	// should find its rung already there rather than force a change to this ladder.
22	export const SIZE_BOUNDS = [20, 50, 100, 200, 500];
23	export const SIZES = [...SIZE_BOUNDS.map((n) => `<${n}`), `${SIZE_BOUNDS.at(-1)}+`];
24	
25	export function proseSize(words) {
26	  const bound = SIZE_BOUNDS.find((n) => words < n);
27	  return bound ? `<${bound}` : `${SIZE_BOUNDS.at(-1)}+`;
28	}
29	
30	const RULE_BULLET = /^- \*\*/;
31	const HEADING = /^(#{2,})\s+(.+?)\s*$/;
32	// A rule's lead-in is bolded, and long ones wrap, so the closing ** may sit
33	// several lines below the bullet marker.
34	const LEAD_IN = /\*\*([\s\S]+?)\*\*/;
35	
36	const wordsIn = (lines) => lines.join('\n').split(/\s+/).filter(Boolean).length;
37	
38	const trimTrailingBlanks = (lines) => {
39	  const out = [...lines];
40	  while (out.length && !out.at(-1).trim()) out.pop();
41	  return out;
42	};
43	
44	// A rule block is a top-level `- **Lead-in**` bullet plus its continuation
45	// lines. A pack whose RULES.md carries no such bullet (its rules are written as
46	// sections) is indexed by heading instead; a pack with neither has no
47	// enumerable rules and carries no index.
48	export function ruleBlocks(markdown) {
49	  const lines = markdown.split('\n');
50	  const byBullet = collect(lines, (line) => RULE_BULLET.test(line));
51	  if (byBullet.length) return byBullet;
52	  return collect(lines, (line) => HEADING.test(line));
53	}
54	
55	function collect(lines, startsBlock) {
56	  const blocks = [];
57	  let current = null;
58	  for (const line of lines) {
59	    if (startsBlock(line)) {
60	      current = [line];
61	      blocks.push(current);
62	    } else if (current) {
63	      // A heading closes the block above it: the text under it belongs to the
64	      // next rule, or to no rule at all.
65	      if (HEADING.test(line)) current = null;
66	      else current.push(line);
67	    }
68	  }
69	  return blocks.map((body) => {
70	    const trimmed = trimTrailingBlanks(body);
71	    const text = trimmed.join('\n');
72	    const bold = LEAD_IN.exec(text);
73	    const heading = HEADING.exec(trimmed[0]);
74	    return {
75	      leadIn: normalizeLeadIn(heading ? heading[2] : bold ? bold[1] : trimmed[0]),
76	      words: wordsIn(trimmed),
77	    };
78	  });
79	}
80	
81	// A lead-in is a sentence fragment carrying inline markup and, where it wraps,
82	// newlines; this is the form a reader would compare two spellings of it in.
83	export function normalizeLeadIn(text) {
84	  return text.replace(/[`*_]/g, '').replace(/\s+/g, ' ').trim().replace(/[—–-]$/, '').trim();
85	}
86	
87	// The README's own index: the rows of the first `| Rule | Severity | Reason |
88	// Enforcement |` table, whose Enforcement cell states the rule's size band
89	// ("prose: <100 words", plus the check that also carries it). Rows are held
90	// against RULES.md by position — the index lists the rules in the order the
91	// prose does — so a row's label stays a human summary rather than a second copy
92	// of the rule's lead-in.
93	export function readmeRuleIndex(readme) {
94	  const rows = [];
95	  let inIndex = false;
96	  for (const line of readme.split('\n')) {
97	    if (!line.startsWith('|')) {
